class ColorPalette {
  String lighten(String hex, double amount) {
    final value = _parseHex(hex);
    int r = (value >> 16) & 0xFF;
    int g = (value >> 8) & 0xFF;
    int b = value & 0xFF;

    r = (r + (amount * 255).round()).clamp(0, 255).toInt();
    g = (g + (amount * 255).round()).clamp(0, 255).toInt();
    b = (b + (amount * 255).round()).clamp(0, 255).toInt();

    return _toHex(r, g, b);
  }

  String darken(String hex, double amount) {
    final value = _parseHex(hex);
    int r = (value >> 16) & 0xFF;
    int g = (value >> 8) & 0xFF;
    int b = value & 0xFF;

    r = (r - (amount * 255).round()).clamp(0, 255).toInt();
    g = (g - (amount * 255).round()).clamp(0, 255).toInt();
    b = (b - (amount * 255).round()).clamp(0, 255).toInt();

    return _toHex(r, g, b);
  }

  int _parseHex(String hex) {
    return int.parse(hex.replaceFirst('#', ''), radix: 16);
  }

  String _toHex(int r, int g, int b) {
    final rr = r.toRadixString(16).padLeft(2, '0').toUpperCase();
    final gg = g.toRadixString(16).padLeft(2, '0').toUpperCase();
    final bb = b.toRadixString(16).padLeft(2, '0').toUpperCase();
    return '#$rr$gg$bb';
  }
}

void main() {
  final palette = ColorPalette();
  final primary = '#FF5722';

  print('Màu gốc: $primary');
  print('Sáng lên 20%: ${palette.lighten(primary, 0.2)}');
  print('Sáng lên 50%: ${palette.lighten(primary, 0.5)}');
  print('Tối đi 20%: ${palette.darken(primary, 0.2)}');
  print('Tối đi 50%: ${palette.darken(primary, 0.5)}');
  print('Clamp khi sáng quá: ${palette.lighten('#FFFFFF', 0.5)}');
}

class ThemeConfig {
  final String mode;
  final Map<String, String> colors;
  ThemeConfig({required this.mode, required this.colors});

  String get backgroundColor => colors['background'] ?? '#FFFFFF';
  String get textColor => colors['text'] ?? '#000000';
}

class ThemeSwitcher {
  String _mode;

  static const _lightColors = {
    'background': '#FFFFFF',
    'surface': '#F5F5F5',
    'text': '#1E293B',
    'textSecondary': '#64748B',
    'primary': '#3B82F6',
    'border': '#E2E8F0',
  };

  static const _darkColors = {
    'background': '#0F172A',
    'surface': '#1E293B',
    'text': '#F1F5F9',
    'textSecondary': '#94A3B8',
    'primary': '#60A5FA',
    'border': '#334155',
  };

  ThemeSwitcher({String initialMode = 'light'}) : _mode = initialMode {
    if (initialMode != 'light' && initialMode != 'dark') {
      throw ArgumentError('Chế độ không hợp lệ: $initialMode');
    }
  }

  String get mode => _mode;
  bool get isDark => _mode == 'dark';

  void toggle() => _mode = _mode == 'light' ? 'dark' : 'light';

  void setMode(String mode) {
    if (mode != 'light' && mode != 'dark') {
      throw ArgumentError('Chế độ không hợp lệ: $mode');
    }
    _mode = mode;
  }

  Map<String, String> getColors() {
    return _mode == 'dark' ? Map.from(_darkColors) : Map.from(_lightColors);
  }

  ThemeConfig getConfig() => ThemeConfig(mode: _mode, colors: getColors());
}

void main() {
  final switcher = ThemeSwitcher();
  print('Mode ban đầu: ${switcher.mode}');

  final light = switcher.getConfig();
  print('Nền sáng: ${light.backgroundColor}');
  print('Chữ sáng: ${light.textColor}');

  switcher.toggle();
  final dark = switcher.getConfig();
  print('Mode sau toggle: ${switcher.mode}');
  print('Nền tối: ${dark.backgroundColor}');
  print('Chữ tối: ${dark.textColor}');

  try {
    switcher.setMode('blue');
  } catch (e) {
    print('setMode blue: lỗi ($e)');
  }
}

class ThemeTokens {
  final String preset;
  ThemeTokens({this.preset = 'default'});

  Map<String, double> get spacing {
    if (preset == 'compact') {
      return {'xs': 2, 'sm': 4, 'md': 8, 'lg': 12, 'xl': 16};
    }
    return {'xs': 4, 'sm': 8, 'md': 16, 'lg': 24, 'xl': 32};
  }

  double get elevation => preset == 'compact' ? 2.0 : 4.0;
}

class TypographyScale {
  final double baseSize;
  final double scale;
  TypographyScale({this.baseSize = 14.0, this.scale = 1.0});

  double h1() => baseSize * 2.0 * scale;
  double body() => baseSize * scale;
  double caption() => baseSize * 0.85 * scale;
}

void main() {
  final tokens = ThemeTokens();
  print('Spacing md (default): ${tokens.spacing['md']}');
  print('Elevation (default): ${tokens.elevation}');

  final compact = ThemeTokens(preset: 'compact');
  print('Spacing md (compact): ${compact.spacing['md']}');
  print('Elevation (compact): ${compact.elevation}');

  final typo = TypographyScale(baseSize: 16.0);
  print('H1: ${typo.h1()}');
  print('Body: ${typo.body()}');
  print('Caption: ${typo.caption()}');
}

