class ColorPalette {
  final String primaryHex;
  final String secondaryHex;
  final String accentHex;

  ColorPalette(this.primaryHex, {String? secondaryHex, String? accentHex})
      : secondaryHex = secondaryHex ?? '#2196F3',
        accentHex = accentHex ?? '#4CAF50';

  int _parseHex(String hex) {
    return int.parse(hex.replaceFirst('#', ''), radix: 16);
  }

  String _toHex(int r, int g, int b) {
    return '#${r.toRadixString(16).padLeft(2, '0').toUpperCase()}'
        '${g.toRadixString(16).padLeft(2, '0').toUpperCase()}'
        '${b.toRadixString(16).padLeft(2, '0').toUpperCase()}';
  }

  String lighten(String hex, double amount) {
    final value = _parseHex(hex);
    int r = (value >> 16) & 0xFF;
    int g = (value >> 8) & 0xFF;
    int b = value & 0xFF;

    r = (r + (amount * 255).round()).clamp(0, 255);
    g = (g + (amount * 255).round()).clamp(0, 255);
    b = (b + (amount * 255).round()).clamp(0, 255);

    return _toHex(r, g, b);
  }

  String darken(String hex, double amount) {
    final value = _parseHex(hex);
    int r = (value >> 16) & 0xFF;
    int g = (value >> 8) & 0xFF;
    int b = value & 0xFF;

    r = (r - (amount * 255).round()).clamp(0, 255);
    g = (g - (amount * 255).round()).clamp(0, 255);
    b = (b - (amount * 255).round()).clamp(0, 255);

    return _toHex(r, g, b);
  }

  List<String> generateShades(String hex) {
    return [
      darken(hex, 0.3),
      darken(hex, 0.15),
      hex,
      lighten(hex, 0.15),
      lighten(hex, 0.3),
    ];
  }

  String describe() {
    return 'Palette(primary=$primaryHex, secondary=$secondaryHex, accent=$accentHex)';
  }
}

