class StyleParser {
  Map<String, String> parse(String styleString) {
    final styles = <String, String>{};
    for (final part in styleString.split(';')) {
      final trimmed = part.trim();
      if (trimmed.isEmpty) continue;
      final idx = trimmed.indexOf(':');
      if (idx == -1) continue;
      final key = trimmed.substring(0, idx).trim();
      final value = trimmed.substring(idx + 1).trim();
      if (key.isNotEmpty) styles[key] = value;
    }
    return styles;
  }
  String build(Map<String, String> styles) {
    return styles.entries.map((e) => '${e.key}: ${e.value}').join('; ');
  }
  String getValue(Map<String, String> styles, String key, {String fallback = ''}) {
    return styles[key] ?? fallback;
  }
  Map<String, String> merge(Map<String, String> base, Map<String, String> override) {
    return {...base, ...override};
  }
